function countryData(){
 const examples=['Russia','France','Finland','Denmark','United States'];
 shell(`<div class="dataset-layout country-data-layout"><div class="dataset-context">`+head('NOTEBOOK 01 · DATA BEFORE THE MODEL','27 countries, <em>one row at a time.</em>','Question: can GDP per capita help estimate a country’s average life-satisfaction score?','ORIGINAL DATA')+`<div class="dataset-facts"><div><strong>27</strong><span>selected countries</span></div><div><strong>1</strong><span>row = one country</span></div></div><dl class="data-definitions"><div><dt>Country · identifier</dt><dd>Each row describes one country. Its name is a label; this model does not use the name to make predictions.</dd></div><div><dt>What we know · input X</dt><dd>GDP per capita is economic output divided by population, in USD as labelled in the source. It is the input: the information we give the model. It is not a salary.</dd></div><div><dt>What we want to predict · target y</dt><dd>The target is the answer we want to predict: average life satisfaction, on a 0–10 scale. <strong>6.9 means 6.9 score points</strong>, not 6.9% or USD6.9.</dd></div></dl><p class="dataset-source">Historical teaching subset assembled by Géron: OECD Better Life Index and World Bank GDP via Our World in Data. The source notebook selects GDP for 2020 and identifies its BLI extract as 2020. This is not a current ranking or a random sample of all countries.</p></div><div class="dataset-preview"><span class="eyebrow">FIVE ACTUAL ROWS · SELECT A COUNTRY</span><table class="data-table country-table"><thead><tr><th>Country</th><th>GDP per capita<br><small>USD / person</small></th><th>Life satisfaction<br><small>score points, 0–10</small></th></tr></thead><tbody>${examples.map(name=>{const i=D.life.findIndex(p=>p.name===name),d=D.life[i];return `<tr data-data-row="${i}"><td><button data-inspect-country="${i}">${esc(name)}</button></td><td>${fmt(d.x,2)}</td><td>${fmt(d.y,1)}</td></tr>`;}).join('')}</tbody></table><div id="dataset-country-detail" class="dataset-readout"></div><p class="dataset-source">These are original CSV values, rounded only for display. Interactive edits later are hypothetical and do not change this table.</p></div></div>`);
 const update=()=>{const d=D.life[state.country];$('#dataset-country-detail').innerHTML=`<span class="eyebrow">READ ONE ROW · ${esc(d.name)}</span><p>Input: <strong>${fmt(d.x,2)} USD per person</strong>.</p><p>Actual score (target y): <strong>${fmt(d.y,1)} life-satisfaction points</strong>.</p><p>Next: use GDP to estimate this score. Compare the estimate with the actual score.</p>`;$$('[data-data-row]').forEach(el=>el.classList.toggle('selected',+el.dataset.dataRow===state.country));};
 $$('[data-inspect-country]').forEach(el=>el.onclick=()=>{state.country=+el.dataset.inspectCountry;update();});update();
}
function housingData(){
 const row=D.housing.rows[D.housing.development[0]],col=name=>row[D.housing.columns.indexOf(name)];
 const fields=[['longitude / latitude','Location · degrees',`${fmt(col('longitude'),2)} / ${fmt(col('latitude'),2)}`],['housing_median_age','Median housing age · years',fmt(col('housing_median_age'))],['total_rooms','All rooms in the district · count',fmt(col('total_rooms'))],['total_bedrooms','All bedrooms in the district · count',col('total_bedrooms')===null?'Missing':fmt(col('total_bedrooms'))],['population','District residents · people',fmt(col('population'))],['households','Households in the district · count',fmt(col('households'))],['median_income','Rescaled median income · approx. USD10,000 units',fmt(col('median_income'),4)],['ocean_proximity','Location relative to ocean · category',col('ocean_proximity')],['median_house_value','Target: median house value · historical USD',`$${fmt(col('median_house_value'))}`]];
 shell(head('NOTEBOOK 02 · CALIFORNIA HOUSING · 1990','A district <em>is not a house.</em>','Question: can a district’s income, location and other details help estimate its typical house value?','ORIGINAL DATA')+`<div class="dataset-layout housing-intro"><div class="dataset-context"><div class="dataset-facts"><div><strong>20,640</strong><span>census block groups (districts)</span></div><div><strong>9 → 1</strong><span>known details → value to predict</span></div></div><dl class="data-definitions"><div><dt>One row = one district</dt><dd>Each row summarizes a small area: its residents, rooms, income and other details. These inputs are also called features. A row does not describe one house. The models in this lesson are regressions: they predict a number.</dd></div><div><dt>Target: median house value</dt><dd>The median is the middle value when prices are sorted from lowest to highest. For $100k, $150k and $800k, it is $150k. Here the target uses historical USD.</dd></div><div><dt>Watch the income scale</dt><dd>A recorded income of <strong>${fmt(col('median_income'),4)}</strong> is approximately <strong>USD${fmt(col('median_income')*10000)}</strong>. The variable is rescaled and capped; it is not a raw dollar amount.</dd></div></dl><p class="dataset-source">1990 California census data distributed with Géron’s chapter2. Full dataset: 207 missing bedroom counts; 965 target values at the recorded cap of USD500,001. Historical district data cannot price a particular home today.</p></div><div class="dataset-preview"><span class="eyebrow">ONE EXAMPLE ROW · WHAT EACH COLUMN MEANS</span><table class="data-table housing-dictionary"><thead><tr><th>Field</th><th>Meaning / unit</th><th>Example</th></tr></thead><tbody>${fields.map(([name,meaning,value],i)=>`<tr class="${i===fields.length-1?'target-row':''}"><td>${name}</td><td>${meaning}</td><td>${value}</td></tr>`).join('')}</tbody></table><p class="dataset-source">Longitude and latitude are two separate input columns, shown together here. The example comes from development data; final-test targets are not used in this introduction.</p></div></div>`);
}
function countryControls(compact=false){return `<div class="control-group"><label for="country">Select a country</label><select id="country">${D.life.map((p,i)=>`<option value="${i}" ${i===state.country?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>${compact?'':`<div class="control-group"><div class="range-label"><label for="country-y">Actual score · y</label><output id="country-y-value"></output></div><input id="country-y" type="range" min="0" max="10" step=".1" value="${lifePoints()[state.country].y}"><label class="edit-mode-label">After editing an observed score</label><div class="stacked-toggle">${btn('refit','Retrain on every edit',state.refit)}${btn('fixed','Keep original fit',!state.refit)}</div></div>`}<div id="country-stats"></div>${compact?'':prompt('After changing a score, what is recalculated in each mode?')+`<details class="definition"><summary>What do fit and predict mean?</summary><div id="fit-definition"></div></details>${useCase('Example: when is a straight line useful?', 'Delivery time tends to rise steadily with distance. A line is a simple first model to try and check on other deliveries.', 'Rush-hour traffic creates sharp changes, or the journey is much longer than any in the data. A line may miss those patterns; compare alternatives on separate data.')}`}<button class="quiet" id="restore-country">Restore original data</button>`;}
function country(){
 shell(head('01 · BUILD THE PREDICTION','How does a regression <em>make a prediction?</em>','Regression predicts a number. Here, GDP per person is the input and life satisfaction is the number to predict. Solid dots show actual scores.','LIVE CALCULATION')+`<div class="workbench regression-layout">${plotFrame('<span>Solid dot = actual · hollow dot = predicted</span><span id="data-badge" class="pill">ORIGINAL DATA</span>','<div class="axis-controls">'+btn('axis-full','Whole rule · GDP = 0',!state.countryZoom)+btn('axis-zoom','Country detail',state.countryZoom)+'</div>'+svgBox())}<div class="model-explainer"><span class="eyebrow">READ THE RULE</span><div id="model-equation"></div></div><aside class="sidebar">${countryControls()}</aside></div>`);
 bindCountry();bind('axis-full','click',()=>{state.countryZoom=false;updateCountry();});bind('axis-zoom','click',()=>{state.countryZoom=true;updateCountry();});updateCountry();
}
function residuals(){
 shell(head('02 · MEASURE ONE MISS','One prediction. <em>Two ways to read its error.</em>','Error = actual score − predicted score. This is called a residual. Keep + or − to see the direction; remove the sign to see only the size.','LIVE CALCULATION')+`<div class="workbench explained">${plotFrame('<span id="residual-label">Signed errors · zero in the centre</span><div class="chart-actions">'+btn('signed-error','Signed error',true)+btn('absolute-error','Absolute error')+'</div>',svgBox(),'<span id="residual-caption">Same countries and line as before. Zero means an exact prediction. These countries helped build the line.</span>')}<aside class="sidebar">${countryControls(true)}<p class="definition-text"><strong>Positive:</strong> the model predicted too low.<br><strong>Negative:</strong> the model predicted too high.<br><strong>Absolute:</strong> how far it missed, in score points.</p>${prompt('What information is lost when we take the absolute error?')}</aside></div>`);
 bindCountry();const mode=absolute=>{state.errorAbs=absolute;animate(state.residual,absolute?1:0,t=>{state.residual=t;updateCountry();});};bind('signed-error','click',()=>mode(false));bind('absolute-error','click',()=>mode(true));updateCountry();
}
