 bind('country','change',e=>{state.country=+e.target.value;if($('#country-y'))$('#country-y').value=lifePoints()[state.country].y;updateCountry();});
 bind('country-y','input',e=>{state.changes[state.country]=+e.target.value;updateCountry();});
 bind('fixed','click',()=>{state.refit=false;updateCountry();});bind('refit','click',()=>{state.refit=true;updateCountry();});
 bind('restore-country','click',()=>{state.changes={};state.refit=true;if($('#country-y'))$('#country-y').value=D.life[state.country].y;updateCountry();});
 let dragging=false;
 $('#plot').addEventListener('pointerdown',e=>{const node=e.target.closest('[data-country]');if(!node)return;state.country=+node.dataset.country;$('#country').value=state.country;if($('#country-y'))$('#country-y').value=lifePoints()[state.country].y;dragging=scenes[state.slide].id==='prediction';updateCountry();e.preventDefault();});
 const move=e=>{if(!dragging)return;const svg=$('#plot');if(!svg)return;const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());const lo=state.countryZoom?4:0,hi=state.countryZoom?9:10,height=svg.viewBox.baseVal.height;const y=Math.max(lo,Math.min(hi,lo+(height-60-pt.y)/(height-105)*(hi-lo)));state.changes[state.country]=Math.round(y*10)/10;$('#country-y').value=state.changes[state.country];updateCountry();};
 const up=()=>{dragging=false;};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);
 const resize=new ResizeObserver(()=>updateCountry());resize.observe($('#plot').parentElement);
 cleanup=()=>{resize.disconnect();window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);};
